svg.script:
(function(){
  var button=document.getElementById("testButton");
  var result=document.getElementById("result");
  var clicks=0;
  function update(){clicks++;result.textContent="SVG render: PASS | JavaScript: PASS ("+clicks+")";}
  button.addEventListener("click",update);
  button.addEventListener("keydown",function(e){if(e.key==="Enter"||e.key===" "){e.preventDefault();update();}});
})();
